"use strict";(globalThis.webpackChunkp_vs_np_docs=globalThis.webpackChunkp_vs_np_docs||[]).push([[6408],{53544(e){e.exports=JSON.parse('{"tag":{"label":"np-complete","permalink":"/azeon/p-vs-np/tags/np-complete","allTagsPath":"/azeon/p-vs-np/tags","count":6,"items":[{"id":"np-completeness/14-3-sat-the-building-block","title":"3-SAT: The Building Block","description":"Why restricting every clause to exactly three literals keeps SAT just as hard, and how the reduction from SAT to 3-SAT actually works step by step.","permalink":"/azeon/p-vs-np/np-completeness/3-sat-the-building-block"},{"id":"complexity-zoo/np-hard-vs-np-complete","title":"NP-Hard vs. NP-Complete","description":"Two labels I\'d been using almost interchangeably. NP-Complete means \'hardest inside NP\'. NP-Hard only means \'at least that hard\', and some NP-Hard problems can\'t be solved by any computer, ever.","permalink":"/azeon/p-vs-np/complexity-zoo/np-hard-vs-np-complete"},{"id":"np-completeness/the-clique-problem","title":"The Clique Problem","description":"What does finding mutual friends in a social network have to do with Boolean logic? The reduction from 3-SAT to Clique is the bridge, and it is one of the most satisfying constructions in all of NP-Completeness.","permalink":"/azeon/p-vs-np/np-completeness/the-clique-problem"},{"id":"np-completeness/the-cook-levin-theorem","title":"The Cook-Levin Theorem","description":"In 1971, Stephen Cook proved that one specific problem sits at the top of the entire NP hierarchy, and that solving it would solve everything else. This is the result that launched the field of NP-Completeness.","permalink":"/azeon/p-vs-np/np-completeness/the-cook-levin-theorem"},{"id":"np-completeness/vertex-cover","title":"The Vertex Cover Problem","description":"Back in Post 11 I used cameras on roads to explain what a reduction is. I never proved that problem was NP-Complete. Today I finally do, and it takes almost no new work.","permalink":"/azeon/p-vs-np/np-completeness/vertex-cover"},{"id":"complexity-zoo/will-quantum-computers-solve-np","title":"Will Quantum Computers Solve NP?","description":"Probably not. There\'s a quantum algorithm that speeds up brute-force search, and a theorem that says, in an important sense, it\'s the best possible. A square root of exponential is still exponential.","permalink":"/azeon/p-vs-np/complexity-zoo/will-quantum-computers-solve-np"}],"unlisted":false}}')}}]);